public class KeyValueStoreTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        KeyValueStore<String, Integer> store = new KeyValueStore<>();
        check("size() when empty", 0, store.size());
        check("containsKey on missing key", false, store.containsKey("a"));
        store.put("a", 1);
        store.put("b", 2);
        store.put("c", 1);
        check("get existing key", 1, store.get("a"));
        check("get missing key returns null", null, store.get("zzz"));
        check("size() after three puts", 3, store.size());
        check("containsKey on present key", true, store.containsKey("b"));
        store.put("a", 9);
        check("put overwrites old value", 9, store.get("a"));
        check("size() unchanged by overwrite", 3, store.size());
        check("getOrDefault on present key", 2, store.getOrDefault("b", -1));
        check("getOrDefault on missing key", -1, store.getOrDefault("zzz", -1));
        store.removeIfValue(1);
        check("removeIfValue removed matching entry", false, store.containsKey("c"));
        check("size() after removeIfValue", 2, store.size());
        check("non-matching entries survive", 9, store.get("a"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

